/* 자동 생성 — 모두의자격\전산세무_가져오기.py. 손으로 고치지 말 것 */
window.TREE={"subject":"세무회계","key":"js_tax","brand":"모두의 자격","parts":[{"no":1,"name":"부가가치세","chs":["1-01"],"color":"--fam-geo"},{"no":2,"name":"소득세","chs":["2-02"],"color":"--fam-soc"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"부가가치세","nodes":[1,2,3,4,5,6]},{"key":"2-02","part":2,"no":2,"name":"소득세","nodes":[7,8,9,10,11,12]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"부가가치세 총칙(납세의무자·과세기간·납세지·사업자등록)","name":"부가가치세 총칙(납세의무자·과세기간·납세지·사업자등록)","vol":16,"q":65},{"no":2,"part":1,"ch":1,"title":"과세대상 거래(재화·용역의 공급·공급시기)","name":"과세대상 거래(재화·용역의 공급·공급시기)","vol":15,"q":63},{"no":3,"part":1,"ch":1,"title":"영세율과 면세","name":"영세율과 면세","vol":11,"q":47},{"no":4,"part":1,"ch":1,"title":"세금계산서","name":"세금계산서","vol":14,"q":57},{"no":5,"part":1,"ch":1,"title":"매출세액과 매입세액(과세표준·매입세액 불공제·대손세액)","name":"매출세액과 매입세액(과세표준·매입세액 불공제·대손세액)","vol":23,"q":93},{"no":6,"part":1,"ch":1,"title":"신고와 납부(예정·확정·환급·간이과세)","name":"신고와 납부(예정·확정·환급·간이과세)","vol":22,"q":90},{"no":7,"part":2,"ch":2,"title":"소득세 총칙(납세의무자·과세기간·납세지)","name":"소득세 총칙(납세의무자·과세기간·납세지)","vol":16,"q":64},{"no":8,"part":2,"ch":2,"title":"종합소득금액의 계산(이자·배당·사업·근로·연금·기타)","name":"종합소득금액의 계산(이자·배당·사업·근로·연금·기타)","vol":45,"q":180},{"no":9,"part":2,"ch":2,"title":"원천징수","name":"원천징수","vol":12,"q":50},{"no":10,"part":2,"ch":2,"title":"종합소득공제·세액공제","name":"종합소득공제·세액공제","vol":24,"q":96},{"no":11,"part":2,"ch":2,"title":"확정신고와 납부","name":"확정신고와 납부","vol":13,"q":55},{"no":12,"part":2,"ch":2,"title":"연말정산","name":"연말정산","vol":14,"q":58}],"stat":{"parts":2,"chs":2,"nodes":12,"q":918},"hx":{"전산세2023_107회-11":"세액공제 한도는 과세기간별이 아니라 연간 기준으로 정해져 있다. 두 과세기간에 걸쳐 합산한다.","전산세2023_107회-12":"과세표준은 총매출액에서 매출에누리를 뺀 17,000,000원이다. 판매장려금은 과세표준에서 빼지 않는다. 17,000,000 × 10% = 1,700,000원.","전산세2023_107회-13":"간이과세자의 의제매입세액공제는 폐지되어 받을 수 없다. 법인 음식점도 공제를 받고, 공제 시기는 공급받은 날이 속하는 신고 때이며, 정규증빙 없는 농어민 구입 공제는 제조업에만 허용된다.","전산세2023_107회-14":"과세소득은 800,000 - 150,000×4일 = 200,000원이다. 산출세액은 200,000 × 6% = 12,000원, 여기서 55%를 공제하면 12,000 × 45% = 5,400원.","전산세2023_107회-15":"한 번의 접대에 3만원(경조금은 20만원)을 넘는 기업업무추진비는 적격증빙이 없으면 필요경비로 인정하지 않는다.","전산세2023_108회-11":"주된 사업과 관련해 용역을 제공하는 과정에서 필연적으로 생기는 재화는 별도의 공급으로 보고, 과세·면세 여부만 주된 사업을 따른다. 주된 용역의 공급에 포함되는 것이 아니다.","전산세2023_108회-12":"예정신고는 법인사업자가 한다. 개인사업자는 원칙적으로 예정고지로 납부한다.","전산세2023_108회-13":"소매업자는 영수증 발급이 원칙이지만 상대방이 세금계산서를 요구하면 발급해야 한다. 요구해도 발급할 수 없는 업종은 미용업, 여객운송업 등으로 따로 정해져 있다.","전산세2023_108회-14":"주주인 임원(소액주주 제외)이 제공받는 사택 이익은 과세되는 근로소득이다. 나머지 셋은 월 20만원 한도 비과세다.","전산세2023_108회-15":"도소매업과 음식점업 사업소득은 서로 통산해 15,000,000원이다. 부동산임대업(주거용 제외)의 결손금은 다른 소득과 통산하지 못하고, 양도소득은 종합소득에 들어가지 않는다. 15,000,000 + 13,000,000 = 28,000,000원.","전산세2023_109회-11":"대가의 각 부분을 받기로 한 때가 공급시기인 경우, 실제로 대가를 받았는지와 관계없이 그때를 공급시기로 본다.","전산세2023_109회-12":"항공기에 의한 여객운송은 과세다. 대중교통 중 시내버스·지하철 등은 면세지만 항공기·우등고속버스·고속철도는 과세한다.","전산세2023_109회-13":"폐업 때 남은 재화는 자기에게 공급한 것으로 보는 간주공급이다. 포괄양도, 물납, 강제경매·공매는 재화의 공급으로 보지 않는다.","전산세2023_109회-14":"복권 당첨금, 일용근로소득, 비실명 이자소득은 원천징수로 끝나는 분리과세다. 위약금·배상금은 기타소득으로 종합과세 대상이다(소득금액 300만원 이하이면 분리과세를 선택할 수 있다).","전산세2023_109회-15":"교육비세액공제에서 대학 등록금은 본인과 직계비속·형제자매 등이 대상이고, 직계존속의 교육비는 공제 대상이 아니다.","전산세2023_110회-11":"자기가 생산한 비영업용 소형승용차를 업무용으로 쓰면 자가공급으로 공급의제다. 나머지 셋은 공급으로 보지 않는다.","전산세2023_110회-12":"영세율의 목적은 소비지국과세원칙에 따른 국제적 이중과세 방지와 외화획득 장려다. 역진성 완화는 면세의 목적이다.","전산세2023_110회-13":"재화나 용역의 공급 없이 세금계산서를 발급하면 공급가액의 3%를 가산세로 낸다.","전산세2023_110회-14":"잉여금 처분에 의한 상여의 수입시기는 해당 법인의 잉여금 처분 결의일이다. 결산일이 아니다.","전산세2023_110회-15":"복식부기의무자가 파는 사업용 유형자산(차량·기계 등)의 양도가액은 총수입금액에 들어간다. 300,000,000 + 30,000,000 = 330,000,000원. 이자수익은 이자소득, 건물 양도는 제외된다.","전산세2023_111회-11":"면세는 토지 공급, 식용 비가공식료품(국내산·외국산 모두), 국선변호인의 국선 변호 3개다. 시외우등고속버스 여객운송과 자동차운전학원 교육용역은 과세이고, 국내에서 공급하는 골동품은 면세 대상인 예술창작품에서 빠져 과세다.","전산세2023_111회-12":"대손세액공제는 공급일부터 10년이 지난 날이 속하는 과세기간의 확정신고기한까지 대손이 확정된 경우에 적용한다. 15년이 아니다.","전산세2023_111회-13":"소득세는 부부를 합산하지 않고 개인별로 과세한다. 과세기간은 변경할 수 없고, 납세지는 주소지가 원칙이며, 퇴직·양도소득은 분류과세라 모든 소득을 합산하지 않는다.","전산세2023_111회-14":"양도소득과 퇴직소득은 종합소득에 들어가지 않는다. 이자소득이 2천만 원을 넘어 종합과세되므로 22,000,000+30,000,000=52,000,000원이다.","전산세2023_111회-15":"1~11월 귀속분을 그 해 12월 31일까지 지급하지 않으면 12월 31일에 지급한 것으로 본다. 11월분을 다음 해 1월 31일에 지급했다면 원천징수 시기는 20x1년 12월 말일이다.","전산세2024_112회-11":"간이과세자가 세금계산서 등을 받은 매입액의 공제율은 공급대가의 0.5%다. 1%가 아니다.","전산세2024_112회-12":"면세농산물 등의 매입가액에는 운임 등 부대비용을 넣지 않는다. 수입하는 경우에는 관세의 과세가격을 기준으로 한다.","전산세2024_112회-13":"비과세되는 학자금은 근로자 본인의 학자금이다. 가족의 학자금은 비과세 대상이 아니다.","전산세2024_112회-14":"근로소득과 사업소득이 함께 있으면 합산해 확정신고해야 한다. 나머지는 연말정산, 분류과세, 분리과세로 납세의무가 끝나 확정신고 면제 대상이다.","전산세2024_112회-15":"기본공제를 받으려면 배우자의 소득금액이 100만 원 이하(근로소득만 있으면 총급여 500만 원 이하)여야 한다. 근로소득금액 500만 원이면 총급여가 500만 원을 훨씬 넘어 대상이 아니다.","전산세2024_113회-11":"사유 발생일을 작성일로 쓰는 경우는 환입, 계약의 해제, 공급가액 증감, 내국신용장 사후 개설이다. 나머지 셋은 처음 작성일로 음수 세금계산서를 발급한다.","전산세2024_113회-12":"필요적 기재사항이 아니라 임의적 기재사항이 빠진 세금계산서의 매입세액은 공제된다.","전산세2024_113회-13":"일반 환급은 확정신고기한이 지난 후 30일 이내에 한다. 25일이 아니다.","전산세2024_113회-14":"금융소득은 연 2천만 원을 넘으면 종합과세가 강제되고, 이하이면 분리과세로 끝난다. 납세자가 고르는 것이 아니다.","전산세2024_113회-15":"해당 과세기간의 결손금을 먼저 다른 소득금액에서 공제하고 남은 소득에서 이월결손금을 공제한다. 순서가 반대로 적혀 있다.","전산세2024_114회-11":"부가가치세는 소비지국 과세원칙을 따른다. 그래서 수출은 영세율을 적용하고 수입에는 부가가치세를 과세한다.","전산세2024_114회-12":"공통매입세액 안분을 생략하는 경우는 면세공급가액 5% 미만이면서 공통매입세액 5백만 원 미만일 때, 공통매입세액 합계 5만 원 미만일 때, 신규사업자가 그 과세기간에 공통사용재화를 공급할 때다. 나는 5백만 원 이상이라 해당하지 않는다.","전산세2024_114회-13":"예정신고한 과세표준과 납부(환급)세액은 확정신고 때 다시 신고하지 않는다. 신규사업자의 최초 예정신고기간은 사업 개시일부터 그 예정신고기간 종료일까지이고, 개인사업자는 예정고지가 원칙이며 일부 사업자만 예정신고할 수 있다.","전산세2024_114회-14":"일용근로소득은 원천징수로 끝나는 분리과세다. 배당소득 2,400만 원은 2천만 원 초과라 종합과세, 부동산 임대소득은 종합과세, 일시 인적용역 대가 800만 원은 기타소득금액(필요경비 60% 적용 시 320만 원)이 300만 원을 넘어 종합과세다.","전산세2024_114회-15":"사업과 관련된 자산수증이익은 총수입금액에 들어간다. 매출세액, 복식부기의무자가 아닌 자의 사업용 고정자산 매각액, 자가생산 제품을 다른 제품 원재료로 쓴 금액은 총수입금액에 넣지 않는다.","전산세2024_115회-11":"일반과세자가 간이과세자로 바뀌면 그 해 간이과세 과세기간은 변경일이 속하는 해의 7월 1일부터 12월 31일까지다. 1월 1일부터 6월 30일은 일반과세 과세기간이다.","전산세2024_115회-12":"사업용 상가건물을 팔면 재화의 공급이다. 담보 제공, 사업의 포괄적 양도, 조세의 물납은 재화의 공급으로 보지 않는다.","전산세2024_115회-13":"보험료·의료비·교육비 세액공제는 근로소득이 있는 거주자에게 주는 공제다. 기부금세액공제는 근로소득이 없어도 받을 수 있다.","전산세2024_115회-14":"소득세법상 장기할부판매의 수입시기는 인도일이다. 대가를 받기로 한 날을 기준으로 삼는 것은 법인세법 쪽 규정이다.","전산세2024_115회-15":"공익법인 시상 상금과 다수가 순위를 겨루는 대회의 상금은 받은 금액의 80%를 필요경비로 본다. 60%는 강연료·원고료 등에 적용한다.","전산세2024_116회-11":"고속철도 여객운송은 과세다. 박물관 입장, 도서 공급, 도서대여는 면세 대상이다.","전산세2024_116회-12":"면세사업 관련, 기업업무추진비 관련, 토지 관련 매입세액은 공제하지 않는다. 제조업자가 면세 농산물을 사서 과세재화를 만들면 의제매입세액을 공제한다.","전산세2024_116회-13":"1~11월분을 그 연도 말까지 지급하지 않으면 12월 31일에, 12월분을 다음 연도 2월 말까지 지급하지 않으면 2월 말일에 지급한 것으로 본다. 12월분을 3월 31일에 지급했다면 20x2년 2월 말일이 지급시기다.","전산세2024_116회-14":"사업용 유형자산 처분이익이 사업소득이 되는 것은 복식부기의무자다. 간편장부대상자의 처분이익은 사업소득이 아니다.","전산세2024_116회-15":"배우자가 있는 여성의 부녀자공제는 종합소득금액 3천만 원 이하가 요건이고 배우자 소득 유무와는 관계없다.","전산세2024_117회-11":"영세율은 세율을 0%로 적용하는 것이라 사업자는 납세의무가 있고 신고도 해야 한다. 매입세액은 환급받는다. 납세의무가 없는 것은 면세다.","전산세2024_117회-12":"위탁판매의 공급시기는 수탁자가 물건을 판매하는 때다. 위탁한 때가 아니다.","전산세2024_117회-13":"주사업장총괄납부는 납부하려는 과세기간 개시 20일 전에 신청한다. 종료일 기준이 아니다.","전산세2024_117회-14":"보험료·의료비·교육비 세액공제는 근로소득에 대한 종합소득산출세액이 한도다. 기부금 세액공제는 이 한도에 묶이지 않는다.","전산세2024_117회-15":"근로소득만 있는 자는 연말정산으로 납세의무가 끝나고, 두 곳 이상에서 받아도 한 곳에서 합산 정산하면 신고하지 않는다. 금융소득 3천만 원은 종합과세 기준 2천만 원을 넘어 신고해야 한다.","전산세2025_118회-11":"구매확인서에 의해 공급하는 재화는 영세율 적용 대상이라 영세율세금계산서를 발급한다. 미용업, 택시운송업, 간주임대료는 발급 의무가 없다.","전산세2025_118회-12":"면세 농산물 등을 원재료로 과세재화·용역을 공급하는 사업자가 대상이고 음식점업 법인도 해당한다. 면세사업자는 매입세액공제 자체가 없고, 가공 없이 파는 소매업은 원재료로 쓰는 경우가 아니며, 간이과세자는 의제매입세액공제를 적용하지 않는다.","전산세2025_118회-13":"직전 1역년의 공급대가가 1억 400만 원 이상이면 그 다음 연도 7월 1일부터 일반과세자가 된다. 20x3년 공급대가 1.2억 원이 기준을 넘으므로 20x4년 7월 1일이다.","전산세2025_118회-14":"소득세법의 저작권 양도·사용 대가 기타소득은 저작자 이외의 자가 받는 것이다. 강연료 12만 원은 60%를 필요경비로 의제해 소득금액이 48,000원이므로 과세최저한(5만 원 이하)에 걸려 과세하지 않는다.","전산세2025_118회-15":"퇴직소득은 분류과세라 종합소득에서 뺀다. 주거용 부동산임대업 결손금은 다른 소득과 통산하고, 비주거용 부동산임대업 결손금은 통산하지 않는다. 4,000,000 + 8,000,000 - 3,000,000 = 9,000,000원이다.","전산세0_교재106회-01":"부가가치세는 납세의무자와 담세자가 다른 간접세이고 국세이며 소비지국 과세원칙과 전단계세액공제법을 쓴다. 그래서 가만 옳다.","전산세0_교재84회-01":"기초재공품은 재료비가 이미 다 들어가 있어 당기 재료비 환산량이 0이다. 당기착수 완성분 3,000개와 기말재공품 2,000개를 더한 5,000개다.","전산세0_교재84회-02":"트럭은 승용차가 아니라서 비영업용 소형승용차 전용에 해당하지 않는다. 나머지는 폐업시 잔존재화, 개인적 공급(경조사 10만 원 초과분), 면세사업 전용이다.","전산세0_교재84회-03":"양도소득과 퇴직소득은 분류과세이므로 제외한다. 배당소득 2,200만 원은 2,000만 원을 넘어 종합과세되므로 22,000,000 + 30,000,000 = 52,000,000원이다.","전산세0_교재77회-01":"생산량이 기계 한 대의 한도를 넘을 때마다 임차료가 한 대분씩 늘어나므로 준고정비의 계단 모양이다.","전산세0_교재92회-01":"총공손은 200 + 600 - 650 - 50 = 100개다. 정상공손은 완성품 650개의 10%인 65개이므로 비정상공손은 35개다.","전산세0_교재86회-01":"총제조원가 1,370,000원에서 재공품 증가분 45,000원을 빼면 당기제품제조원가 1,325,000원이다. 620,000 + 1,325,000 - 매출원가 1,350,000 = 595,000원이 기말제품이다.","전산세0_교재18회-01":"부가가치세는 납세의무자(사업자)와 담세자(최종소비자)가 다른 간접세다.","전산세0_교재18회-02":"도소매업 같은 일반 사업소득은 거래 때 세금계산서를 주고받으므로 원천징수하지 않는다.","전산세0_교재18회-03":"결정세액에 가산세를 더하면 총결정세액이고, 여기서 기납부세액을 빼야 차감 납부할 세액이 된다.","전산세0_교재51회-01":"상속으로 사업자 명의가 바뀌는 것은 폐업이 아니라 사업자등록 정정 사유다.","전산세0_교재51회-02":"영업용으로 산 승용차를 영업 외 용도로 쓰면 비영업용 소형승용차 전용으로 간주공급이다. 작업복 제공, 사용 목적 사업장 반출, 일반적인 자가공급은 공급으로 보지 않는다.","전산세0_교재51회-03":"사적연금의 총연금액이 연 1,500만 원 이하이면 납세의무자가 분리과세를 선택할 수 있다.","전산세0_교재62회-01":"중대한 오류는 소급법으로 자산, 부채, 자본의 기초 금액에 반영한다. 전진적으로 처리하는 것은 회계추정의 변경이다.","전산세0_교재62회-02":"주택임대는 면적과 관계없이 면세이고 토지의 공급도 면세다. 주택 부수 토지가 아닌 토지의 임대와 국민주택이 아닌 건물의 공급은 과세다.","전산세0_교재62회-03":"수출 재화는 발급이 면제되지만 내국신용장·구매확인서로 공급하는 재화는 국내 사업자 사이의 거래라서 면제되지 않는다.","전산세0_교재66회-01":"상표권을 양도하는 것은 권리라는 무체물을 넘기는 것이므로 재화의 공급이다. 나머지는 시설이나 권리를 쓰게 하거나 역무를 제공하는 용역이다.","전산세0_교재66회-02":"④는 직전 면세비율이 5% 미만이지만 공통사용재화 공급가액이 5,000만 원 이상이라서 안분한다. ①은 50만 원 미만, ②는 직전 과세기간이 없고 ③은 5% 미만에 5,000만 원 미만이라서 안분하지 않는다.","전산세0_교재66회-03":"소득세는 단계별 초과누진세율을 적용해 소득이 많은 사람에게 더 높은 세율을 매긴다.","전산세0_교재59회-01":"기말제품재고액은 손익계산서의 매출원가 계산에 나오는 항목이다. 제조원가명세서는 재공품까지만 다룬다.","전산세0_교재59회-02":"일용근로 6%, 복권당첨 20%, 비영업대금이익 25%, 비실명이자 45% 순이므로 라-나-가-다이다.","전산세0_교재76회-01":"조세의 물납은 재화의 공급이 아니다. 폐업시 잔존재화, 사업상 증여, 특수관계인에게 하는 부동산 임대용역 무상공급은 공급으로 본다.","전산세0_교재61회-01":"주된 공급이 면세거래이면 부수 공급도 면세가 된다. 주된 사업이 과세든 면세든 부수 재화가 면세대상이면 면세다.","전산세0_교재63회-01":"선입선출법은 기초재공품원가를 당기발생원가와 구분해 전부 완성품원가에 넣는다. 둘을 합쳐 배분하는 쪽은 평균법이다.","전산세0_교재57회-01":"예정배부율은 예산액을 예정조업도로 나눈 값이고, 예정배부액은 여기에 각 제품의 실제 배부기준량을 곱해 구한다.","전산세0_교재57회-02":"두 효과를 구분하기 어려우면 회계추정의 변경으로 본다.","전산세0_교재57회-03":"계약금이 위약금으로 대체되는 경우의 위약금은 원천징수 대상에서 제외된다.","전산세0_교재36회-01":"계약금 받기로 한 날 다음 날부터 인도일까지 6개월 이상이고 대가를 나눠 받으므로 중간지급조건부 판매다. 공급시기는 대가의 각 부분을 받기로 한 때, 즉 세 날짜 모두다.","전산세0_교재36회-02":"소득세 납세지는 사업장이 아니라 주소지(서초세무서)이고, 두 사업장의 소득을 합산해 신고한다. 사업장별로 나뉘는 것은 부가가치세다.","전산세0_교재36회-03":"고용관계 없는 일시적 강연료는 기타소득이다. 1,200,000 x 40% x 20% x 1.1 = 105,600원이다.","전산세0_교재45회-01":"생산량이 늘어나는 만큼 총원가가 비례해 늘고 단위당 원가는 1,500원으로 일정하므로 변동비다.","전산세0_교재45회-02":"비정상공손은 발생한 기간의 비용(영업외비용)으로 처리하고 완성품이나 기말재공품에 배부하지 않는다.","전산세0_교재45회-03":"보장성보험료 세액공제는 근로소득이 있어야 받는다. 인적공제, 자녀·결혼세액공제, 연금 관련 공제, 기부금 관련 공제는 근로소득이 없어도 받는다.","전산세0_교재45회-04":"이자소득은 소액부징수 규정이 적용되지 않아 1천 원 미만이어도 징수한다.","전산세0_교재102회-01":"완성도기준지급조건부 판매의 공급시기는 대가의 각 부분을 받기로 한 때다.","전산세0_교재147회-01":"선박·항공기의 외국항행용역은 영세율 대상이다. 자동차대여는 과세, 주택임대와 도서대여는 면세다.","전산세0_교재56회-01":"취득원가는 주당 5,000원(7,000원에서 평가이익 주당 2,000원을 뺀 값)이다. 처분금액 500주×6,000과 취득원가 500주×5,000의 차이로 처분이익 500,000원이다.","전산세0_교재34회-01":"신문, 복권, 토지의 매매, 수돗물, 보험용역 5개가 면세다. 해외건설공사는 영세율, 일반의약품과 전기는 과세다.","전산세0_교재44회-01":"영세율 대상 재화·용역을 공급하는 면세사업자는 면세를 포기하고 과세사업자가 되어 매입세액을 공제받을 수 있다. 면세포기는 언제든 신고하면 되고 승인은 필요 없다.","전산세0_교재58회-01":"재료비·노무비·제조경비로 먼저 집계하고, 그다음 보조·제조부문별로 모은 뒤, 마지막에 제조부문 원가를 제품에 배부한다.","전산세0_교재58회-02":"주식배당을 하면 주식을 새로 발행하므로 발행주식수는 늘어난다. 자본 총액만 변하지 않는다.","전산세0_교재58회-03":"판매비와관리비는 급여, 소모품비, 감가상각비, 기업업무추진비, 세금과공과를 합한 5,500,000원이다. 30,000,000 - 20,000,000 - 5,500,000 = 4,500,000원이고, 이자수익과 기부금은 영업외 항목이다.","전산세0_교재85회-01":"처분 전 장부금액은 전기말 공정가치 10,000,000원이다. 처분금액 8,000,000원과 비교하면 처분손실 2,000,000원이다.","전산세0_교재83회-01":"예정배부액은 실제 직접노무시간에 예정배부율을 곱한 값이다. 400,000원 / 50시간 = 시간당 8,000원이다.","전산세0_교재83회-02":"소득세는 종합과세를 원칙으로 하지만 분류과세와 분리과세 소득은 합산하지 않는다.","전산세0_교재83회-03":"일시적 인적용역의 대가는 총수입금액의 60%가 필요경비이다. 기타소득금액 80만 원에 20%를 곱해 160,000원이다.","전산세0_교재90회-01":"당기제품제조원가는 500,000 + 10,500,000 - 2,000,000 = 9,000,000원이다. 여기에 기초제품을 더하고 기말제품을 빼면 매출원가 8,000,000원이다.","전산세0_교재90회-02":"구매부문은 주문횟수나 주문수량으로 배분한다. 기계시간은 수선유지부문 같은 곳의 기준이다.","전산세0_교재80회-01":"건물관리는 건물 사용면적, 식당은 종업원 수, 창고는 창고 사용면적이나 재료사용량으로 나눈다. 복리후생부문은 종업원 수가 맞다.","전산세0_교재80회-02":"예정배부액은 실제작업시간 5,000시간 x 2,500원 = 12,500,000원이다. 과대배부 300,000원이므로 실제발생액은 이보다 300,000원 적은 12,200,000원이다.","전산세0_교재69회-01":"조업도가 변해도 총원가가 같은 것은 고정비의 행태다. 전기요금은 기본요금에 사용량 요금이 붙는 준변동비라 맞지 않는다.","전산세0_교재69회-02":"평균법과 선입선출법의 가공비 환산량 차이는 기초재공품이 이미 가공된 부분이다. 10,000 x 20% = 2,000개다.","전산세0_교재69회-03":"당기에 생긴 결손금을 먼저 공제하고, 그다음에 이월결손금을 공제한다.","전산세0_교재87회-01":"비례조정이면 매출원가에 3/5인 600,000원이 더해지고, 매출원가조정법이면 1,000,000원이 더해진다. 매출원가가 400,000원 더 늘어 매출총이익은 400,000원 감소한다.","전산세0_교재87회-02":"물량흐름, 완성품환산량, 배분할 원가 집계, 단위당 원가, 마지막으로 완성품과 기말재공품에 원가를 나누는 순서다.","전산세0_교재87회-03":"비용으로 처리할 것을 자산으로 올렸으므로 자산과 당기순이익이 커지고 비용은 작아진다. 순이익이 커지니 자본도 과대계상된다.","전산세0_교재39회-01":"상호배부법은 보조부문 사이의 용역 관계를 모두 반영하므로 순서를 정할 필요가 없다. 용역 관계가 중요할 때 쓰고 절차는 가장 복잡하다.","전산세0_교재16년8월특별회차-01":"계약이 해제되어 재화가 공급되지 않았다면 수정세금계산서의 작성일은 계약해제일이다.","전산세0_교재16년8월특별회차-02":"조기환급을 받으려는 사업자가 확정신고서를 냈다면 확정신고기한 경과 후 15일 이내에 환급한다.","전산세0_교재55회-01":"기초재공품 + 당기총제조원가 = 당기제품제조원가 + 기말재공품이므로, 기말재공품이 더 크면 당기총제조원가가 당기제품제조원가보다 크다.","전산세0_교재55회-02":"보조부문비를 가장 정확하게 배부하는 방법은 상호배부법이다.","전산세0_교재37회-01":"B는 장기할부가 아닌 단기할부라서 재화가 인도되는 때에 발급한다. C는 월합계 세금계산서를 다음 달 10일까지 발급해야 하므로 틀렸다. A와 D는 적절하다.","전산세0_교재37회-02":"기장세액공제와 재해손실세액공제는 사업소득이 있을 때, 근로소득세액공제는 근로소득이 있을 때 적용한다.","전산세0_교재96회-01":"배부율은 250,000원 / 직접노무비 500,000원 = 0.5다. 유람선B의 제조간접비는 200,000 x 0.5 = 100,000원이므로 총제조원가는 600,000 + 200,000 + 100,000 = 900,000원.","전산세0_교재96회-02":"6세 이하 자녀의 보육수당은 월 20만 원 이하 금액이 비과세이다.","전산세0_교재82회-01":"이자 상당액은 이미 포함돼 있고 금전 판매장려금은 차감하지 않는다. 장려물품은 사업상 증여라서 1,000,000원을 더하면 101,000,000원이다.","전산세0_교재82회-02":"상용근로소득과 사업소득은 모두 종합과세라 합산하면 세액이 달라지므로 확정신고를 해야 한다.","전산세0_교재91회-01":"공장에서 쓴 간접재료비, 보험료, 공장장 급여, 기계 감가상각비, 공장 임차료를 더한 580,000원이 제조원가다. 영업부 항목은 판매비와관리비라 뺀다.","전산세0_교재100회-01":"매출원가 550,000원에서 거꾸로 올라가면 당기제품제조원가는 540,000원이다. 기초재공품 30,000원을 빼고 기말재공품 10,000원을 더하면 당기총제조원가 520,000원이다.","전산세0_교재100회-02":"직접배분법은 보조부문 상호 간 용역을 뺀다. 설비 300,000원 중 절단 몫은 600/1,000로 180,000원, 동력 250,000원 중 절단 몫은 200/500로 100,000원이다. 900,000 + 180,000 + 100,000 = 1,180,000원.","전산세0_교재67회-01":"단기매매증권이 시장성을 잃으면 반드시 매도가능증권으로 옮긴다. 채무증권은 만기보유증권으로도 분류할 수 있고, 매도가능증권과 만기보유증권은 서로 재분류할 수 있으며, 매도가능증권은 장기투자 목적이다.","전산세0_교재67회-02":"전세권과 임차보증금은 비유동자산 중 기타비유동자산이다. 산업재산권, 라이선스, 임차권리금은 무형자산이다.","전산세0_교재43회-01":"재무제표에는 추정에 의한 측정치가 포함된다. 추정을 허용하지 않는다는 설명은 틀렸다.","전산세0_교재131회-01":"의제매입세액 계산의 매입가액에는 운임 등 취득부대비용이 들어가지 않는다.","전산세0_교재98회-01":"중요한 항목은 본문이나 주석에 구분해서 표시해야 한다. 성격이 비슷한 항목과 합쳐 표시할 수 있는 것은 중요하지 않은 항목이다.","전산세0_교재65회-01":"수선부문 총원가는 자기 발생원가 20,000원에 동력부문이 수선부문에 준 20%를 더한 것이고, 동력부문은 30,000원에 수선부문이 준 30%를 더한 것이다.","전산세0_교재64회-01":"의제매입세액은 면세농산물을 사용한 때가 아니라 구입한 때가 속하는 신고기간에 공제한다.","전산세0_교재25회-01":"기말재고자산은 기말재료 30,000원과 기말재공품 40,000원을 더한 70,000원이다. 당기총제조비용은 470,000원, 당기제품제조원가는 450,000원이다.","전산세0_교재70회-01":"제품 쪽에서 당기 완성량은 1,000 + 50 - 100 = 950개다. 재공품 쪽에서 기초재공품 + 착수 800개 = 완성 950개이므로 기초재공품은 150개다.","전산세0_교재70회-02":"검사시점이 기말재공품 완성도보다 앞이면 공손이 완성품과 기말재공품 양쪽에서 나온 것이므로 정상공손원가를 둘에 나눠 부담시킨다.","전산세0_교재105회-01":"추적가능성으로 나누면 직접원가와 간접원가가 된다. 제조원가와 비제조원가는 이 기준의 분류가 아니다.","전산세0_교재97회-01":"사용액은 기초재고에 매입액을 더하고 기말재고를 뺀 값이다. 기말재고가 200,000원 많으니 매입액은 사용액보다 200,000원 많은 3,200,000원이다.","전산세0_교재97회-02":"제품매출원가는 제품 계정의 대변에서 매출원가 계정으로 넘어간다. 재공품 계정 대변에서 나가는 것은 완성품원가다.","전산세0_교재60회-01":"기본원가는 직접재료비와 직접노무비이고 전환원가는 직접노무비와 제조간접비다. 두 쪽에 모두 들어가는 것은 직접노무비다.","전산세0_교재60회-02":"일용근로자의 산출세액은 (일급여 - 15만 원)에 6%의 단일세율을 곱해 구한다.","전산세0_교재68회-01":"제조간접비는 6,500,000원의 30%인 1,950,000원이고, 이것이 직접노무비의 75%이므로 직접노무비는 2,600,000원이다. 총제조원가에서 둘을 빼면 직접재료비 1,950,000원이 남는다.","전산세0_교재68회-02":"순위 경쟁 대회 상금은 총수입금액의 80%가 필요경비이므로 원천징수세액은 총수입금액의 4%(= 20% x 20%)이다. 40만 원 ÷ 4% = 1,000만 원이다.","전산세0_교재15회-01":"계약의 위약·해약으로 받는 위약금, 배상금과 그 법정이자는 기타소득이다.","전산세0_교재15회-02":"상용근로소득만 있는 자는 소득이 전액 연말정산되므로 확정신고를 하지 않아도 된다.","전산세0_교재52회-01":"기존 건물이 있는 토지를 사서 건물을 헐 때 철거 관련 비용은 토지의 취득원가에 가산한다. 건물 취득원가가 아니다.","전산세0_교재41회-01":"사업 과정에서 생긴 예금 이자는 사업소득이 아니라 이자소득으로 과세한다.","전산세0_교재50회-01":"1주택자라도 기준시가 12억 원을 넘는 고가주택이나 국외 소재 주택의 임대소득은 과세한다.","전산세0_교재75회-01":"기본원가는 직접재료비와 직접노무비의 합이라 제조간접비는 들어가지 않는다. 가공원가는 직접노무비와 제조간접비의 합이다.","전산세0_교재38회-01":"반품률을 합리적으로 추정할 수 있는 상태로 판매·인도한 상품은 매출로 잡으므로 판매자의 재고에서 빠진다. 나머지는 모두 (주)태성의 재고에 든다.","전산세0_교재88회-01":"기본요금과 사용량 요금이 함께 붙는 원가는 준변동비이고 혼합원가라고도 부른다. 계단원가는 준고정비의 다른 이름이다.","전산세0_교재47회-01":"이종자산끼리 바꿀 때는 제공한 자산의 공정가치로 취득원가를 정한다. 장부금액으로 정하는 쪽은 동종자산 교환이다.","전산세0_교재54회-01":"예정배부율은 1,500,000 / 30,000 = 시간당 50원이고 예정배부액은 36,900 x 50 = 1,845,000원이다. 실제발생액 1,650,000원보다 195,000원 많으니 과대배부다.","전산세0_교재17회-01":"일용근로자 근로소득의 원천징수세율은 6%이다.","전산세0_교재28회-01":"다수의 측정자가 독립적으로 측정해도 비슷한 결과가 나온다는 것은 검증가능성이다. 중립성은 편견이나 편의가 없어야 한다는 뜻이다.","전산세0_교재93회-01":"양도소득은 원천징수하지 않고 양도인이 양도소득세를 예정신고한다.","전산세0_교재32회-01":"제품 홍보비는 광고선전비로 판매비와관리비에 들어간다. 나머지 셋은 공장에서 제품을 만드는 데 쓰인 원가다.","전산세0_교재99회-01":"원가와 원가대상 사이에 추적할 수 있는 인과관계가 있는 기준이 가장 이상적이다. 인과관계를 알기 어려울 때 수혜기준이나 부담능력기준을 쓴다.","전산세0_교재33회-01":"사용 중이던 건물을 허물고 새 건물을 짓는다면 헐리는 건물의 장부금액과 철거비용은 유형자산처분손실로 처리한다. 신축 건물 취득원가에 넣지 않는다.","전산세0_교재12회-01":"중간예납은 사업소득이 있는 거주자가 하며 신규사업자는 제외한다. 근로소득·기타소득만 있는 자는 사업소득이 없어 대상이 아니다.","전산세0_교재78회-01":"재료비는 기초재공품 분을 빼고 당기착수 완성 1,000개와 기말 500개를 더해 1,500개다. 가공비는 300 x 30% + 1,000 + 500 x 40% = 1,290개다."}};
